# (capitolo, testo, [(parola, comando), ...])
SC = [
 # ------------------------------------------------------------------ INTRO
 (0, f"Estate del 1964, mare Adriatico. Un peschereccio di Fano tira su la rete, e insieme al pesce c'è una statua di bronzo, grande come un uomo, fatta più di duemila anni fa.",
  [("Estate", "cal:ESTATE|1964"), ("peschereccio", "mare:fondo"), ("rete", "mare:rete"), ("statua", "i:statue_crust|SAGOMA STILIZZATA · NON È L'OPERA"), ("duemila", "big:2.000+|anni di età")]),
 (0, f"Nessuno la denuncia. Viene nascosta, venduta per {M35} di lire, portata fuori dall'Italia. E tredici anni dopo un museo della California la compra per quasi quattro milioni di dollari.",
  [("Nessuno", "stamp:NESSUNA DENUNCIA"), ("nascosta", "i:cabbage|NASCOSTA"), ("venduta", "big:3,5 mln|di lire · 1964"), ("fuori", "map:Fano|4|Fano,Malibu|Fano>Malibu"), ("quattro", "big:3,95 mln $|1977")]),
 (0, f"Da allora l'Italia la rivuole indietro. Ci sono voluti processi, perizie, ricorsi, una sentenza della Cassazione e una della Corte europea dei diritti dell'uomo. E la statua, a quanto risulta, è ancora là.",
  [("Da", "i:scales|L'ITALIA LA RIVUOLE"), ("processi", "iii:gavel|PROCESSI|magnifier|PERIZIE|letter|RICORSI"), ("Cassazione", "iii:court|CASSAZIONE|strasbourg|CORTE EUROPEA|scales|"), ("ancora", "sala:statua|ANCORA IN CALIFORNIA")]),
 (0, f"In questo fascicolo vedremo il ritrovamento, il nascondiglio, i processi degli anni Sessanta, il viaggio verso l'America, e la lunga battaglia per riportarla a casa.",
  [("In", "cover"), ("ritrovamento", "iii:net|LA RETE|cabbage|IL NASCONDIGLIO|gavel|I PROCESSI"), ("viaggio", "i:plane|IL VIAGGIO"), ("battaglia", "t:L'ATLETA DI FANO · 1964-2024")]),
 # ------------------------------------------------------------------ 1 L'ADRIATICO, 1964
 (1, f"Partiamo dal luogo. Fano è una città della costa marchigiana, in provincia di Pesaro e Urbino, con un porto di pescherecci. Più a sud, sulla stessa costa, c'è Pedaso, in provincia di Fermo.",
  [("Partiamo", "map:Fano|60|Fano"), ("porto", "i:boat|UN PORTO DI PESCHERECCI"), ("Pedaso", "map:Fano|60|Fano,Pedaso"), ("Fermo", "t:LA COSTA MARCHIGIANA")]),
(1, f"Fano ha un passato antico. In epoca romana si chiamava Fanum Fortunae, ed era una tappa della via Flaminia, la strada che collegava Roma alla costa adriatica. In centro c'è ancora l'arco d'Augusto. Una città abituata alla storia, ma non a ripescarla dal mare.",
  [("Fano", "map:Roma|20|Roma,Fano|Roma>Fano"), ("Flaminia", "flow:ROMA>FANO · VIA FLAMINIA"), ("l'arco", "i:fortress|L'ARCO D'AUGUSTO"), ("mare", "mare:vuoto|LA STORIA SOTTO IL MARE")]),
 (1, f"Tra Fano e Pedaso ci sono circa cento chilometri in linea d'aria. Teniamo a mente questi due nomi, perché sul punto esatto del ritrovamento si discuterà per decenni.",
  [("Tra", "flow:FANO>PEDASO"), ("cento", "big:≈ 100 km|in linea d'aria · calcolo nostro"), ("Teniamo", "i:question|DOVE ESATTAMENTE?"), ("decenni", "stamp:DECENNI")]),
 (1, f"Siamo nel pieno del boom economico. L'Italia cresce, e con lei il mare Adriatico diventa sempre più trafficato: pescherecci a strascico che trascinano le reti sul fondo, giorno e notte.",
  [("Siamo", "cal:IL BOOM|1964"), ("Adriatico", "map:Mare Adriatico|30|Fano,Pedaso,Croazia"), ("strascico", "mare:fondo|LA PESCA A STRASCICO"), ("notte", "t:LE RETI SUL FONDO")]),
 (1, f"La pesca a strascico funziona così: la rete viene calata e trainata vicino al fondale. Raccoglie quello che trova. Di solito pesci e fango. A volte, anche altro.",
  [("La", "i:net|LA RETE A STRASCICO"), ("calata", "mare:rete"), ("pesci", "ii:fishing|PESCI|mud|FANGO"), ("altro", "i:question|ANCHE ALTRO")]),
 (1, f"Il fondo del mare Adriatico, infatti, custodisce resti di navi antiche. Per secoli è stato una via di commercio tra la Grecia, i Balcani e la penisola italiana.",
  [("Il", "mare:vuoto|IL FONDALE"), ("navi", "i:oldship|NAVI ANTICHE"), ("Grecia", "map:Mare Adriatico|10|Atene,Fano|Atene>Fano"), ("italiana", "t:UNA VIA DI COMMERCIO")]),
 (1, f"E che cosa dice la legge italiana del 1964? È in vigore la legge 1089 del 1939 sulla tutela delle cose d'interesse artistico e storico. Le cose antiche ritrovate appartengono allo Stato.",
  [("E", "h:E la\n*legge*?"), ("1089", "doc:LEGGE 1089/1939|Tutela delle cose|d'interesse artistico|e storico|RICOSTRUZIONE GRAFICA"), ("antiche", "flow:REPERTO TROVATO>APPARTIENE ALLO STATO"), ("Stato", "stamp:DELLO STATO")]),
 (1, f"Chi trova per caso un oggetto antico deve denunciarlo alle autorità. Chi lo tiene, lo nasconde o lo compra sapendo da dove viene, rischia un processo. Questa regola sarà al centro di tutta la storia.",
  [("Chi", "fig:worker|CHI TROVA"), ("denunciarlo", "i:policecar|DENUNCIA ALLE AUTORITÀ"), ("compra", "iii:house|CHI NASCONDE|money|CHI COMPRA|gavel|IL PROCESSO"), ("regola", "t:LA REGOLA")]),
 (1, f"Un'ultima informazione sui soldi. Nel 1964 la lira ha un cambio fisso con il dollaro: circa 625 lire per un dollaro. È il cambio fisso nato dagli accordi di Bretton Woods, alla fine della seconda guerra mondiale. Ci servirà per confrontare i prezzi di questa storia.",
  [("Un'ultima", "i:calc|UN CONTO"), ("cambio", "flow:625 LIRE>1 DOLLARO"), ("625", "t:CAMBIO FISSO DEGLI ANNI SESSANTA"), ("prezzi", "ii:lire|LIRE|dollar|DOLLARI")]),
 # ------------------------------------------------------------------ 2 I PROTAGONISTI
 (2, f"Apriamo la bacheca dei protagonisti. Al centro c'è lei: la statua. Un giovane in bronzo, nudo, a grandezza naturale. Oggi è alta {H151} centimetri, perché i piedi non ci sono più.",
  [("Apriamo", "board:0"), ("statua", "i:statue|SAGOMA STILIZZATA · NON È L'OPERA"), ("grandezza", "big:151,5 cm|altezza attuale · senza i piedi"), ("piedi", "t:I PIEDI NON CI SONO PIÙ")]),
 (2, f"Il giovane alza la mano destra verso la testa: sta per mettersi una corona, probabilmente d'ulivo. La corona d'ulivo era il premio dei vincitori ai giochi di Olimpia. Per questo lo chiamano l'atleta vittorioso.",
  [("Il", "i:statue_wreath|IL GESTO · SCHEMA"), ("corona", "i:wreath|UNA CORONA D'ULIVO"), ("Olimpia", "map:Olimpia|20|Olimpia"), ("vittorioso", "i:olympia|L'ATLETA VITTORIOSO")]),
 (2, f"Gli occhi, in origine, erano inseriti con un altro materiale e oggi mancano. Sulla data le fonti non coincidono: per il museo che la espone è stata fatta tra il 300 e il 100 avanti Cristo; altre fonti la collocano nel quarto secolo.",
  [("Gli", "i:eye|GLI OCCHI: OGGI MANCANO"), ("data", "h:Quando è\nstata *fatta*?"), ("300", "tl:300 a.C.|INIZIO;200 a.C.|;100 a.C.|FINE"), ("quarto", "t:IV-II SECOLO A.C. · LE FONTI NON COINCIDONO")]),
(2, f"Una statua come questa è rarissima. Nell'antichità le statue di bronzo erano moltissime, ma quasi tutte sono state fuse nei secoli successivi per riutilizzare il metallo. Molti degli originali greci arrivati fino a noi vengono proprio dal mare, come i Bronzi di Riace, trovati in Calabria nel 1972.",
  [("Una", "stamp:RARISSIMA"), ("fuse", "i:fire|FUSE PER IL METALLO"), ("mare", "mare:vuoto|SALVATE DAL MARE"), ("Riace", "cal:RIACE|1972")]),
 (2, f"Come si faceva una statua così? Con la tecnica della cera persa: un modello in cera sopra un nucleo di terra, coperto da uno stampo; la cera si scioglie e al suo posto si cola il bronzo. Le parti grandi, come la testa, spesso venivano fuse a parte e poi unite.",
  [("Come", "h:Come si faceva\nuna *statua*?"), ("cera", "flow:MODELLO IN CERA>STAMPO"), ("bronzo", "flow:LA CERA SI SCIOGLIE>SI COLA IL BRONZO"), ("testa", "i:statue|LA TESTA FUSA A PARTE")]),
 (2, f"Il secondo gruppo: i pescatori di Fano. Secondo le carte dei processi, i pescherecci erano due, con i loro comandanti. Non faremo i loro nomi: non sono mai stati condannati.",
  [("Il", "board:1"), ("pescherecci", "ii:boat|PESCHERECCIO|boat|PESCHERECCIO"), ("comandanti", "fig:worker|I COMANDANTI"), ("nomi", "stamp:NESSUN NOME")]),
 (2, f"Il terzo gruppo: tre fratelli di Gubbio, in Umbria, che comprano la statua, e un sacerdote che la tiene in casa per alcuni mesi. Saranno processati e, come vedremo, assolti.",
  [("Il", "board:2"), ("Gubbio", "map:Gubbio|60|Gubbio,Fano"), ("sacerdote", "i:priest|LA CASA DI UN SACERDOTE"), ("assolti", "stamp:ASSOLTI")]),
 (2, f"Il quarto: un mercante d'arte di Monaco di Baviera, in Germania, che all'inizio degli anni Settanta ha la statua nella sua galleria e la fa restaurare.",
  [("Il", "board:3"), ("Monaco", "map:Monaco di Baviera|12|Monaco di Baviera,Fano"), ("galleria", "i:easel|UNA GALLERIA D'ARTE"), ("restaurare", "i:lab|IL RESTAURO")]),
 (2, f"Il quinto: il museo {GT} di {MB}, in California, voluto dal petroliere americano {JPG}, uno degli uomini più ricchi del mondo e grande collezionista d'arte antica.",
  [("Il", "board:4"), ("California", "map:Malibu|12|Malibu"), ("petroliere", "i:barrel|IL PETROLIO"), ("collezionista", "i:museum|UN COLLEZIONISTA")]),
 (2, f"E infine lo Stato italiano: il ministero della Cultura, i carabinieri del nucleo per la tutela del patrimonio, la procura e il tribunale di Pesaro, la Cassazione. Sono loro a chiedere che la statua torni.",
  [("E", "board:5"), ("ministero", "iii:ministry|MINISTERO|policecar|CARABINIERI|court|TRIBUNALI"), ("Pesaro", "map:Pesaro|60|Pesaro,Fano"), ("torni", "t:I PROTAGONISTI")]),
 (2, f"E poi c'è un nome che compare in quasi ogni articolo: Lisippo. Lisippo di Sicione è uno dei più grandi scultori greci del quarto secolo avanti Cristo, celebre per i ritratti di Alessandro Magno. Plinio il Vecchio gli attribuiva circa millecinquecento opere, ma degli originali in bronzo non ne è rimasto quasi nessuno: li conosciamo soprattutto da copie romane in marmo.",
  [("E", "h:E *Lisippo*?"), ("Sicione", "map:Atene|20|Atene,Olimpia"), ("scultori", "i:chisel|UNO SCULTORE GRECO"), ("Alessandro", "card:LISIPPO|scultore greco|IV secolo a.C.|ritratti di Alessandro Magno")]),
 (2, f"Molti hanno attribuito la statua a Lisippo o alla sua scuola. Ma non c'è nessuna firma, e diversi studiosi non sono d'accordo. Per questo diremo l'Atleta di Fano: è il nome più prudente.",
  [("Molti", "i:statue|ATTRIBUITA A LISIPPO?"), ("firma", "stamp:NESSUNA FIRMA"), ("studiosi", "i:critic|STUDIOSI IN DISACCORDO"), ("prudente", "t:L'ATLETA DI FANO")]),
 # ------------------------------------------------------------------ 3 LA RETE
 (3, f"Come ci è arrivata, una statua greca, in fondo all'Adriatico? Nessuno lo sa con certezza. L'ipotesi più diffusa è quella di una nave antica, probabilmente romana, che la trasportava dalla Grecia.",
  [("Come", "h:Come ci è\n*arrivata*?"), ("certezza", "stamp:NESSUNA CERTEZZA"), ("nave", "mare:nave|L'IPOTESI: UNA NAVE ANTICA"), ("Grecia", "map:Mare Adriatico|10|Atene,Fano|Atene>Fano")]),
 (3, f"Nei secoli in cui Roma conquista la Grecia, molte opere d'arte greche vengono portate in Italia. Secondo questa ipotesi la nave affonda, e la statua resta sul fondo.",
  [("Nei", "ii:temple|LA GRECIA|crown|ROMA"), ("opere", "i:crate|OPERE PORTATE IN ITALIA"), ("affonda", "mare:nave|LA NAVE AFFONDA"), ("fondo", "t:IPOTESI · NON PROVATA")]),
 (3, f"Il museo {GT} ipotizza anche dove si trovasse prima: forse a Olimpia, il santuario dei giochi, o nella città natale dell'atleta. Ma anche questa è un'ipotesi, non un fatto.",
  [("Il", "i:museum|L'IPOTESI DEL MUSEO"), ("Olimpia", "map:Olimpia|30|Olimpia"), ("natale", "i:house|LA CITTÀ DELL'ATLETA?"), ("un'ipotesi", "stamp:IPOTESI")]),
 (3, f"Torniamo al 1964. È estate. Secondo diverse fonti il giorno è il 14 agosto, la vigilia di Ferragosto. Due pescherecci partiti da Fano stanno lavorando in mare aperto.",
  [("Torniamo", "cal:FERRAGOSTO|1964"), ("14", "cal:LA VIGILIA|14 AGO"), ("Due", "mare:fondo|DUE PESCHERECCI"), ("aperto", "t:IN MARE APERTO")]),
 (3, f"Dove? Secondo i giudici italiani, al largo di Pedaso, davanti alla costa delle Marche. Secondo il museo {GT}, in acque internazionali. È il primo grande disaccordo di questa storia.",
  [("Dove", "h:*Dove*?"), ("Pedaso", "map:Pedaso|30|Pedaso,Fano"), ("internazionali", "map:Mare Adriatico|25|Pedaso,Croazia"), ("disaccordo", "stamp:VERSIONI DIVERSE")]),
 (3, f"La rete viene tirata su e dentro c'è qualcosa di pesante. Una figura umana, coperta di incrostazioni marine e di fango. Sembra un uomo, ma è di metallo.",
  [("La", "mare:rete|LA RETE SALE"), ("pesante", "i:anchor|QUALCOSA DI PESANTE"), ("incrostazioni", "i:statue_crust|COPERTA DI INCROSTAZIONI"), ("metallo", "t:È DI BRONZO")]),
 (3, f"La statua viene portata a bordo. Che cosa pensino in quel momento i pescatori, non lo sappiamo. Sappiamo che cosa fanno: non la riportano in mare. E non chiamano nessuno.",
  [("La", "mare:bordo|A BORDO"), ("pescatori", "fig:worker|I PESCATORI"), ("Sappiamo", "i:question|CHE COSA FANNO"), ("nessuno", "stamp:NESSUNA CHIAMATA")]),
 (3, f"Un dettaglio che conterà moltissimo, cinquant'anni dopo: i pescherecci battono bandiera italiana. Per i giudici italiani, quando la statua sale a bordo, è come se entrasse in territorio italiano.",
  [("Un", "i:boat|BANDIERA ITALIANA"), ("cinquant'anni", "cal:50 ANNI DOPO|2010"), ("giudici", "court:LA TESI DEI GIUDICI"), ("territorio", "flow:A BORDO>TERRITORIO ITALIANO")]),
 (3, f"Facciamo un conto. Se la statua è stata fatta tra il 300 e il 100 avanti Cristo, nel 1964 aveva tra i duemilasessanta e i duemiladuecentosessanta anni. Più di venti secoli, in gran parte sul fondo del mare.",
  [("Facciamo", "i:calc|UN CONTO"), ("300", "flow:300-100 A.C.>1964"), ("duemilasessanta", "big:≈ 2.100-2.300|anni · calcolo nostro"), ("secoli", "mare:vuoto|PIÙ DI VENTI SECOLI")]),
 # ------------------------------------------------------------------ 4 IL NASCONDIGLIO
 (4, f"I pescherecci rientrano nel porto di Fano. La statua viene sbarcata senza dire niente a nessuno: né alla capitaneria, né ai carabinieri, né alla soprintendenza.",
  [("I", "mare:rotta|RIENTRO A FANO"), ("porto", "map:Fano|60|Pedaso,Fano|Pedaso>Fano"), ("capitaneria", "iii:anchor|CAPITANERIA|policecar|CARABINIERI|ministry|SOPRINTENDENZA"), ("nessuno", "stamp:SILENZIO")]),
 (4, f"Il primo nascondiglio è a Carrara di Fano, una frazione nell'entroterra: la casa di un conoscente di uno dei pescatori. Secondo le ricostruzioni, la statua viene sotterrata in un campo di cavoli.",
  [("Il", "map:Fano|80|Fano"), ("Carrara", "i:house|CARRARA DI FANO"), ("conoscente", "fig:man|UN CONOSCENTE"), ("cavoli", "i:cabbage|UN CAMPO DI CAVOLI")]),
 (4, f"Immaginiamo la scena: una statua greca di bronzo, sepolta sotto un orto della campagna marchigiana. È lì che passa i suoi primi giorni fuori dal mare dopo più di duemila anni.",
  [("Immaginiamo", "h:Immaginiamo\nla *scena*"), ("sepolta", "i:spade|SOTTO UN ORTO"), ("campagna", "i:cabbage|CAMPAGNA MARCHIGIANA"), ("mare", "t:I PRIMI GIORNI FUORI DAL MARE")]),
 (4, f"Poi arrivano i compratori. Sono tre fratelli di Gubbio. La pagano {M35} di lire. Al cambio di allora, sono circa {K56} dollari.",
  [("Poi", "fig:suit|I COMPRATORI"), ("Gubbio", "map:Gubbio|60|Fano,Gubbio|Fano>Gubbio"), ("pagano", "big:3,5 mln|di lire · 1964"), ("cambio", "flow:3,5 MLN DI LIRE>≈ 5.600 $")]),
 (4, f"Quanto sono, oggi? Con l'indice dei prezzi americano, {K56} dollari del 1964 corrispondono a circa {K58} dollari di oggi. Una bella cifra per dei pescatori, ma tenetela a mente: vedremo quanto diventerà.",
  [("Quanto", "h:Quanto sono\n*oggi*?"), ("l'indice", "flow:5.600 $ (1964)>≈ 58.000 $ DI OGGI"), ("pescatori", "i:money|PER I PESCATORI"), ("diventerà", "t:INDICE DEI PREZZI USA (CPI) · CALCOLO NOSTRO")]),
 (4, f"La statua lascia la costa e sale verso l'Appennino, fino a Gubbio, in Umbria. Sono circa sessantacinque chilometri in linea d'aria da Fano.",
  [("La", "map:Gubbio|50|Fano,Gubbio|Fano>Gubbio"), ("l'Appennino", "i:mountain|L'APPENNINO"), ("sessantacinque", "big:≈ 65 km|da Fano a Gubbio · calcolo nostro")]),
 (4, f"A Gubbio viene nascosta nella casa di un sacerdote, lontano dagli occhi dei curiosi. Resta in quella casa fino al maggio del 1965.",
  [("A", "i:priest|LA CASA DEL SACERDOTE"), ("maggio", "cal:FINO A|MAG 1965")]),
 (4, f"Poi la statua sparisce. Viene venduta a compratori rimasti sconosciuti, e da quel momento non si sa più dove sia. Per alcuni anni, nessuna traccia.",
  [("Poi", "stamp:SPARITA"), ("sconosciuti", "i:nophoto|COMPRATORI SCONOSCIUTI"), ("traccia", "i:question|NESSUNA TRACCIA")]),
 (4, f"Una cosa è certa: a un certo punto la statua esce dall'Italia. Senza nessuna licenza di esportazione. Come e quando, esattamente, nessuna fonte lo stabilisce con certezza.",
  [("Una", "map:Gubbio|12|Gubbio,Monaco di Baviera|Gubbio>Monaco di Baviera"), ("licenza", "doc:LICENZA DI ESPORTAZIONE|nessuna richiesta|nessuna autorizzazione||RICOSTRUZIONE GRAFICA"), ("nessuna", "stamp:SENZA LICENZA"), ("certezza", "i:question|COME E QUANDO?")]),
 (4, f"Facciamo il punto. Agosto 1964: la statua esce dal mare. Poi un campo di cavoli, poi Gubbio, poi la vendita. Nel giro di meno di un anno, dell'Atleta non si sa più niente.",
  [("Facciamo", "tl:AGO 1964|IL MARE;1964|I CAVOLI;1964-65|GUBBIO;1965|SPARITA"), ("Nel", "t:MENO DI UN ANNO"), ("niente", "stamp:SPARITA")]),
 # ------------------------------------------------------------------ 5 I PROCESSI
 (5, f"Ma la vicenda non resta segreta. La notizia di una statua antica ripescata e venduta arriva alle autorità, e parte un'indagine.",
  [("Ma", "i:statue|NON RESTA SEGRETA"), ("notizia", "i:envelope|LA NOTIZIA"), ("autorità", "i:policecar|LE AUTORITÀ"), ("un'indagine", "i:magnifier|L'INDAGINE")]),
 (5, f"L'accusa riguarda i tre fratelli di Gubbio e il sacerdote. Il reato contestato è previsto proprio dalla legge del 1939: aver ricevuto e tenuto un bene che, secondo l'accusa, apparteneva allo Stato.",
  [("L'accusa", "board:2"), ("reato", "doc:CAPO D'IMPUTAZIONE|ricettazione|art. 67 L. 1089/1939||RICOSTRUZIONE GRAFICA"), ("ricevuto", "flow:BENE DELLO STATO?>RICETTAZIONE"), ("Stato", "t:SECONDO L'ACCUSA")]),
 (5, f"Il processo si svolge a Perugia. In primo grado il tribunale assolve tutti e quattro.",
  [("Il", "map:Perugia|60|Perugia,Gubbio"), ("primo", "court:PRIMO GRADO · PERUGIA"), ("assolve", "stamp:ASSOLTI")]),
 (5, f"Ma l'accusa fa appello, e la Corte d'appello di Perugia ribalta la decisione: i tre fratelli vengono condannati per ricettazione, il sacerdote per aver aiutato a nascondere la statua.",
  [("Ma", "court:APPELLO · PERUGIA"), ("ribalta", "i:scales|LA DECISIONE SI RIBALTA"), ("condannati", "stamp:CONDANNATI"), ("sacerdote", "i:priest|IL SACERDOTE")]),
 (5, f"Non è finita. Questa volta ricorrono gli imputati. Nel 1968 la Corte di cassazione annulla la condanna e rimanda il processo a un'altra corte d'appello. Si ricomincia da capo.",
  [("Non", "h:Non è\n*finita*"), ("1968", "court:CASSAZIONE · 1968"), ("annulla", "stamp:ANNULLATA")]),
 (5, f"Nel novembre del 1970 arriva la decisione finale: tutti assolti. Su quale corte abbia pronunciato quest'ultima sentenza, Perugia o Roma, le fonti non coincidono. Sull'esito, sì: assolti.",
  [("Nel", "cal:LA FINE|NOV 1970"), ("assolti", "stamp:ASSOLTI"), ("Perugia", "ii:court|PERUGIA?|court|ROMA?"), ("Sull'esito", "t:TUTTI ASSOLTI")]),
 (5, f"Perché? La Cassazione, molti anni dopo, scriverà che mancavano le prove sui fatti. Secondo altre ricostruzioni, il punto debole era uno: non si riusciva a dimostrare che la statua fosse stata trovata in acque italiane.",
  [("Perché", "h:*Perché*?"), ("prove", "stamp:PROVE INSUFFICIENTI"), ("ricostruzioni", "i:question|ACQUE ITALIANE?"), ("italiane", "map:Mare Adriatico|25|Pedaso,Croazia")]),
 (5, f"Il museo {GT} racconterà questa vicenda a modo suo: secondo il museo, già la Cassazione del 1968 non aveva trovato prove che la statua appartenesse all'Italia. È la tesi che il museo ripeterà per decenni.",
  [("Il", "i:museum|LA VERSIONE DEL MUSEO"), ("1968", "doc:LA TESI DEL MUSEO|1968: nessuna prova|che la statua|appartenga all'Italia|RICOSTRUZIONE GRAFICA"), ("decenni", "t:LA TESI DEL MUSEO")]),
 (5, f"Fermiamoci un momento. Anni di processi, quattro decisioni, e nessun colpevole. Intanto la statua non è più in Italia, e nessuno sa dove sia.",
  [("Fermiamoci", "tl:1° GRADO|ASSOLTI;APPELLO|CONDANNATI;1968|ANNULLATO;1970|ASSOLTI"), ("nessun", "stamp:NESSUN COLPEVOLE"), ("dove", "i:question|DOV'È LA STATUA?")]),
 (5, f"Se questi casi vi interessano, iscrivetevi a Fascicolo Italia: ogni giorno un nuovo caso.",
  [("Se", "subscribe")]),
 # ------------------------------------------------------------------ 6 MONACO DI BAVIERA
 (6, f"La statua ricompare all'inizio degli anni Settanta in Germania, a Monaco di Baviera, nella galleria di un mercante d'arte. È lì che la vedono studiosi e possibili compratori.",
  [("La", "map:Monaco di Baviera|14|Gubbio,Monaco di Baviera|Gubbio>Monaco di Baviera"), ("galleria", "sala:statua|MONACO DI BAVIERA|LA GALLERIA · SCHEMA"), ("studiosi", "fig:expert|GLI STUDIOSI")]),
 (6, f"Il mercante la fa restaurare. Bisogna togliere le incrostazioni marine e pulire il bronzo, lavorando con cautela su un metallo rimasto in acqua per secoli. Il restauro viene fatto a Monaco.",
  [("Il", "i:lab|IL RESTAURO"), ("incrostazioni", "ii:statue_crust|PRIMA|statue|DOPO"), ("cautela", "i:magnifier|UN LAVORO DI PRECISIONE"), ("Monaco", "t:IL RESTAURO A MONACO")]),
 (6, f"Dentro la statua restano materiali del nucleo usato per la fusione. Gli esperti li analizzano con il metodo del carbonio quattordici, e la datazione indica l'età antica: intorno al quarto secolo avanti Cristo.",
  [("Dentro", "i:statue|IL NUCLEO DI FUSIONE"), ("carbonio", "i:carbon|CARBONIO 14"), ("datazione", "big:IV sec. a.C.|la prima datazione · 1974")]),
 (6, f"Il mercante chiama anche un archeologo britannico, Bernard {AS}. A metà degli anni Settanta arriva la prima attribuzione a Lisippo. Il nome di un grande scultore fa salire, inevitabilmente, l'interesse dei musei.",
  [("Il", "fig:expert|UN ARCHEOLOGO BRITANNICO"), ("Bernard", "card:BERNARD ASHMOLE|archeologo britannico|esamina la statua"), ("attribuzione", "stamp:LISIPPO?"), ("musei", "i:museum|L'INTERESSE DEI MUSEI")]),
 (6, f"L'Italia, intanto, l'ha ritrovata. Nel 1973 i carabinieri accertano che la statua è a Monaco, e le autorità italiane chiedono a quelle tedesche di sequestrarla e di procedere contro chi la possiede.",
  [("L'Italia", "map:Monaco di Baviera|30|Monaco di Baviera"), ("1973", "cal:LA RICHIESTA|1973"), ("carabinieri", "i:policecar|I CARABINIERI"), ("sequestrarla", "stamp:RICHIESTA DI SEQUESTRO")]),
 (6, f"Ma non funziona. Tra il 1973 e il 1974 le autorità tedesche lasciano cadere le richieste italiane e archiviano il caso. In Germania la statua resta libera di essere venduta.",
  [("Ma", "cal:ARCHIVIATO|1973-74"), ("archiviano", "stamp:ARCHIVIATO"), ("Germania", "t:LIBERA DI ESSERE VENDUTA")]),
 (6, f"In Germania, insomma, l'Italia non riesce a far valere le sue ragioni. E in mano non ha nessuna condanna: il processo italiano si era chiuso con l'assoluzione di tutti.",
  [("In", "map:Monaco di Baviera|30|Monaco di Baviera"), ("condanna", "stamp:NESSUNA CONDANNA"), ("l'assoluzione", "court:ASSOLTI · 1970")]),
 (6, f"Intanto la proprietà cambia ancora. La statua passa a un consorzio d'arte chiamato Artemis, con sede in Lussemburgo e una filiale a Londra. Sarà lui a venderla.",
  [("Intanto", "i:handshake|LA PROPRIETÀ CAMBIA"), ("Artemis", "card:ARTEMIS|consorzio d'arte|sede in Lussemburgo|filiale a Londra"), ("Londra", "map:Lussemburgo|10|Monaco di Baviera,Lussemburgo,Londra"), ("venderla", "t:IL VENDITORE")]),
 (6, f"Facciamo il punto sul viaggio fin qui: il fondale davanti alle Marche, Fano, un campo di cavoli, Gubbio, poi la Germania. Il prossimo passo è il più lungo: l'Atlantico.",
  [("Facciamo", "map:Gubbio|10|Pedaso,Fano,Gubbio,Monaco di Baviera|Pedaso>Fano>Gubbio>Monaco di Baviera"), ("Germania", "tl:1964|IL MARE;1964|FANO;1965|GUBBIO;1973|MONACO"), ("l'Atlantico", "i:waves|L'ATLANTICO")]),
 # ------------------------------------------------------------------ 7 IL MUSEO GETTY
 (7, f"Il compratore è {JPG}. Il petroliere ha già un museo nella sua proprietà di {MB}, sulla costa della California, in un edificio costruito sul modello di una villa romana di Ercolano, la villa dei Papiri, ed è da anni un grande collezionista di antichità greche e romane.",
  [("Il", "card:J. PAUL GETTY|petroliere americano|collezionista"), ("villa", "sala:vuoto|LA VILLA DI MALIBU"), ("California", "map:Malibu|14|Malibu"), ("collezionista", "iii:krater|VASI|statue|STATUE|antique|ANTICHITÀ")]),
 (7, f"Le trattative cominciano all'inizio degli anni Settanta. E {GT} pone una condizione: la provenienza deve essere in regola. Secondo i documenti citati dalla Corte europea, chiede di vedere le sentenze italiane.",
  [("Le", "cal:LE TRATTATIVE|ANNI '70"), ("condizione", "stamp:UNA CONDIZIONE"), ("provenienza", "doc:CONDIZIONE|provenienza in regola|sentenze italiane||RICOSTRUZIONE GRAFICA"), ("sentenze", "i:folder|LE SENTENZE")]),
 (7, f"Le sentenze italiane, in effetti, esistono: e dicono che gli imputati sono stati assolti. Il museo si affida ai pareri dei legali del venditore, secondo cui l'Italia non ha alcun diritto sulla statua.",
  [("Le", "court:ASSOLTI · 1970"), ("legali", "fig:suit|I LEGALI DEL VENDITORE"), ("diritto", "stamp:NESSUN DIRITTO?")]),
 (7, f"Il prezzo, però, è altissimo per l'epoca, e la questione della provenienza resta aperta. Le trattative vanno avanti per anni, tra lettere, pareri e incontri.",
  [("Il", "i:money|IL PREZZO"), ("provenienza", "i:question|LA PROVENIENZA"), ("anni", "i:hourglass|ANNI DI TRATTATIVE"), ("lettere", "iii:letter|LETTERE|folder|PARERI|meeting|INCONTRI")]),
 (7, f"Nel 1976 {JPG} muore, mentre la trattativa è ancora aperta. La decisione passa al consiglio del {TR}, l'ente che gestisce il museo e la sua enorme eredità.",
  [("Nel", "cal:MUORE GETTY|1976"), ("consiglio", "fig:suit|IL CONSIGLIO DEL TRUST"), ("eredità", "i:bank|IL TRUST")]),
(7, f"Un dettaglio curioso: {JPG} viveva da anni in Inghilterra, e il museo della villa di {MB} aprì al pubblico nel 1974. Lui, a quanto raccontano le biografie, non lo vide mai di persona. La statua arriverà dopo la sua morte.",
  [("Un", "map:Londra|20|Londra,Malibu"), ("Inghilterra", "i:house|LA SUA CASA IN INGHILTERRA"), ("1974", "cal:APRE IL MUSEO|1974"), ("morte", "stamp:MAI VISTO")]),
 (7, f"Nel 1977 il {TR} compra la statua per {M395} di dollari. Il contratto viene firmato nel Regno Unito. Per l'epoca, un prezzo altissimo.",
  [("Nel", "cal:L'ACQUISTO|1977"), ("compra", "big:3,95 mln $|il prezzo pagato"), ("Regno", "map:Londra|30|Londra"), ("prezzo", "doc:CONTRATTO|firmato nel Regno Unito|3.950.000 dollari||RICOSTRUZIONE GRAFICA")]),
 (7, f"Facciamo il conto promesso. Da {K56} dollari a {M395}. Sono circa settecento volte tanto in tredici anni. E anche tenendo conto dell'inflazione americana, il prezzo cresce di circa trecentosessanta volte.",
  [("Facciamo", "i:calc|IL CONTO"), ("circa", "big:× 705|in valore nominale · calcolo nostro"), ("dell'inflazione", "big:× 360|tenendo conto dell'inflazione (CPI USA)"), ("trecentosessanta", "t:CALCOLO NOSTRO · INDICE DEI PREZZI USA")]),
 (7, f"E oggi? Con l'indice dei prezzi americano, {M395} di dollari del 1977 corrispondono a più di venti milioni di dollari di oggi.",
  [("E", "h:E *oggi*?"), ("l'indice", "flow:3,95 MLN $ (1977)>OLTRE 20 MLN $ DI OGGI"), ("venti", "t:INDICE DEI PREZZI USA (CPI) · CALCOLO NOSTRO")]),
 (7, f"Ad agosto del 1977 la statua arriva negli Stati Uniti, a Boston. Da lì raggiunge la California, e dal 1978 è esposta nella villa del museo, a {MB}.",
  [("Ad", "map:Boston|8|Monaco di Baviera,Boston|Monaco di Baviera>Boston"), ("Boston", "i:crate|ARRIVO A BOSTON · AGO 1977"), ("California", "map:Malibu|5|Boston,Malibu|Boston>Malibu"), ("esposta", "sala:statua|DAL 1978 · LA VILLA DI MALIBU")]),
 (7, f"Calcoliamo la distanza: da Fano a {MB} sono circa diecimila chilometri in linea d'aria. Una statua che per secoli era rimasta ferma sul fondo del mare, in pochi anni fa il giro di mezzo mondo.",
  [("Calcoliamo", "map:Malibu|4|Fano,Malibu|Fano>Malibu"), ("diecimila", "big:≈ 10.000 km|da Fano a Malibu · calcolo nostro"), ("mondo", "t:MEZZO MONDO")]),
 (7, f"Per il museo è un capolavoro. È uno dei pochi bronzi greci a grandezza naturale sopravvissuti, diventa uno dei pezzi più famosi della collezione, e i visitatori la conoscono con il nome inglese che significa giovane vittorioso.",
  [("Per", "sala:statua|IL CAPOLAVORO DEL MUSEO|IL MUSEO · SCHEMA|3"), ("visitatori", "crowd"), ("vittorioso", "card:IL NOME INGLESE|«Victorious Youth»|il giovane vittorioso")]),
 # ------------------------------------------------------------------ 8 L'ITALIA LA RIVUOLE
 (8, f"L'Italia non si arrende. Già nel 1977, appena la statua arriva in America, le autorità italiane si muovono, anche attraverso l'Interpol, per l'esportazione illegale.",
  [("L'Italia", "i:scales|L'ITALIA LA RIVUOLE"), ("arrende", "stamp:NON SI ARRENDE"), ("l'Interpol", "i:globe2|INTERPOL"), ("l'esportazione", "map:Boston|8|Fano,Boston")]),
 (8, f"Per molti anni, però, le richieste non portano a nulla. All'estero pesa sempre la stessa obiezione: in Italia, per quella statua, nessuno è stato condannato.",
  [("Per", "i:hourglass|ANNI DI RICHIESTE"), ("obiezione", "stamp:L'OBIEZIONE"), ("condannato", "court:NESSUN CONDANNATO")]),
  (8, f"Nel 1989 il ministero italiano chiede ufficialmente al museo la restituzione della statua. La risposta è un rifiuto. Il museo considera l'acquisto legittimo.",
  [("Nel", "cal:LA RICHIESTA|1989"), ("restituzione", "doc:RICHIESTA DI RESTITUZIONE|Ministero|1989||RICOSTRUZIONE GRAFICA"), ("rifiuto", "stamp:NO"), ("legittimo", "i:museum|ACQUISTO LEGITTIMO, DICE IL MUSEO")]),
 (8, f"Negli anni Duemila, però, il clima cambia. Diversi musei americani sono sotto pressione per pezzi archeologici usciti illegalmente dall'Italia, e cominciano le trattative per le restituzioni.",
  [("Negli", "cal:IL CLIMA CAMBIA|2006"), ("musei", "iii:museum|MUSEI USA|krater|REPERTI|scales|TRATTATIVE"), ("restituzioni", "t:LE RESTITUZIONI")]),
 (8, f"Nel 2007 il ministero e il museo {GT} trovano un accordo: circa quaranta oggetti tornano in Italia. Ma l'Atleta resta fuori dall'accordo. Se ne parlerà dopo, aspettando la giustizia italiana.",
  [("Nel", "cal:L'ACCORDO|2007"), ("quaranta", "big:≈ 40|oggetti restituiti all'Italia"), ("resta", "stamp:L'ATLETA ESCLUSO"), ("giustizia", "court:SI ASPETTA IL TRIBUNALE")]),
 (8, f"A Pesaro, intanto, la procura apre un nuovo procedimento sulla vicenda. L'accusa principale riguarda l'esportazione illegale della statua, uscita dall'Italia senza alcuna licenza.",
  [("A", "map:Pesaro|60|Fano,Pesaro"), ("procura", "i:folder|IL NUOVO PROCEDIMENTO"), ("l'esportazione", "doc:L'ACCUSA|esportazione illegale|senza licenza||RICOSTRUZIONE GRAFICA"), ("licenza", "stamp:SENZA LICENZA")]),
 (8, f"Ma sono passati più di quarant'anni. Nel novembre del 2007 il giudice delle indagini preliminari di Pesaro archivia: i reati sono prescritti. Nessun processo.",
  [("Ma", "big:43 anni|dal ritrovamento · calcolo nostro"), ("novembre", "cal:ARCHIVIAZIONE|NOV 2007"), ("prescritti", "stamp:PRESCRITTO"), ("processo", "t:NESSUN PROCESSO")]),
 (8, f"Sembrerebbe la fine. Invece la procura tenta un'altra strada: la confisca. Non si punisce nessuno, ma si chiede che il bene torni allo Stato, ovunque si trovi.",
  [("Sembrerebbe", "h:Sembra\nla *fine*"), ("confisca", "stamp:CONFISCA"), ("punisce", "flow:NESSUNA PENA>IL BENE TORNA ALLO STATO"), ("ovunque", "map:Malibu|5|Fano,Malibu")]),
(8, f"Qual è la differenza? La prescrizione cancella la possibilità di punire qualcuno per un reato, dopo un certo numero di anni. La confisca di un bene culturale, invece, guarda all'oggetto: non chiede chi è colpevole, chiede di chi è la statua.",
  [("Qual", "h:Qual è la\n*differenza*?"), ("prescrizione", "ii:hourglass|PRESCRIZIONE|statue|CONFISCA"), ("colpevole", "flow:CHI È COLPEVOLE?>DI CHI È LA STATUA?"), ("statua", "t:LA DOMANDA CAMBIA")]),
 (8, f"Facciamo il punto, a metà del viaggio. Il mare nel 1964, Gubbio, Monaco, la vendita nel 1977, {MB}. Poi decenni di richieste respinte. Ora la partita si sposta in tribunale.",
  [("Facciamo", "tl:1964|IL MARE;1965|GUBBIO;1973|MONACO;1977|MALIBU;2007|PESARO"), ("decenni", "stamp:RESPINTE"), ("tribunale", "court:LA PARTITA IN TRIBUNALE")]),
 # ------------------------------------------------------------------ 9 LA CONFISCA
 (9, f"Il 10 febbraio 2010 il giudice di Pesaro ordina la confisca della statua, ovunque si trovi. È la prima vittoria italiana in un tribunale.",
  [("Il", "cal:10 FEBBRAIO|2010"), ("confisca", "doc:ORDINANZA|confisca della statua|«ovunque si trovi»|Pesaro, 2010|RICOSTRUZIONE GRAFICA"), ("vittoria", "stamp:PRIMA VITTORIA")]),
 (9, f"Le motivazioni sono due. Primo: i pescherecci battevano bandiera italiana, quindi la statua è entrata in territorio italiano quando è salita a bordo.",
  [("Le", "h:Due\n*motivazioni*"), ("pescherecci", "mare:bordo|BANDIERA ITALIANA"), ("territorio", "flow:A BORDO>TERRITORIO ITALIANO")]),
 (9, f"Secondo: il museo, per il giudice, è stato negligente. Al momento dell'acquisto sapeva delle richieste italiane, e si è affidato ai legali del venditore invece di chiedere alle autorità italiane.",
  [("Secondo", "i:museum|IL MUSEO"), ("negligente", "stamp:NEGLIGENZA"), ("legali", "ii:suit|I LEGALI DEL VENDITORE|ministry|LE AUTORITÀ ITALIANE")]),
 (9, f"Il museo risponde che l'ordinanza è sbagliata, nel metodo e nel merito. E comincia una lunga battaglia di procedura. Seguiamola, perché spiega perché ci sono voluti altri otto anni.",
  [("Il", "i:museum|LA RISPOSTA DEL MUSEO"), ("sbagliata", "card:LA TESI DEL MUSEO|ordinanza sbagliata|nel metodo e nel merito"), ("otto", "big:8 anni|di procedura")]),
 (9, f"Nel 2011 la Cassazione rimanda il caso a Pesaro. Nel 2012 il giudice di Pesaro conferma la confisca. Il museo fa di nuovo ricorso.",
  [("Nel", "tl:2010|CONFISCA;2011|CASSAZIONE;2012|CONFERMA"), ("conferma", "stamp:CONFERMATA"), ("ricorso", "i:letter|NUOVO RICORSO")]),
 (9, f"Nel 2014 la Cassazione solleva una questione davanti alla Corte costituzionale: un procedimento di questo tipo può svolgersi senza un'udienza pubblica?",
  [("Nel", "cal:CASSAZIONE|2014"), ("Corte", "court:CORTE COSTITUZIONALE"), ("un'udienza", "i:question|UN'UDIENZA PUBBLICA?")]),
 (9, f"Nel 2015 la Corte costituzionale risponde: le parti devono poter chiedere un'udienza pubblica. Così, a ottobre, la Cassazione annulla la decisione del 2012. Si ricomincia.",
  [("Nel", "cal:CONSULTA|2015"), ("pubblica", "crowd"), ("annulla", "stamp:ANNULLATA"), ("ricomincia", "t:SI RICOMINCIA")]),
 (9, f"[L'8|L'otto] giugno 2018, dopo un'udienza pubblica, il giudice di Pesaro conferma ancora una volta la confisca. Il museo ricorre in Cassazione.",
  [("L'8", "cal:8 GIUGNO|2018"), ("un'udienza", "court:UDIENZA PUBBLICA · PESARO"), ("conferma", "stamp:CONFERMATA"), ("Cassazione", "i:letter|RICORSO IN CASSAZIONE")]),
 (9, f"Il 30 novembre 2018 la terza sezione penale della Cassazione respinge il ricorso. La sentenza, depositata il 2 gennaio 2019, porta il numero 22. La confisca è definitiva.",
  [("Il", "cal:30 NOVEMBRE|2018"), ("respinge", "stamp:RICORSO RESPINTO"), ("depositata", "doc:SENTENZA N. 22/2019|Corte di cassazione|terza sezione penale|depositata il 2/1/2019|RICOSTRUZIONE GRAFICA"), ("definitiva", "t:CONFISCA DEFINITIVA")]),
 (9, f"Che cosa dice la Cassazione? Che i beni culturali ritrovati si presumono di proprietà dello Stato, e che la confisca non è una pena: serve a recuperare un bene che appartiene alla collettività.",
  [("Che", "h:Che cosa dice\nla *Cassazione*?"), ("presumono", "flow:BENE CULTURALE>PROPRIETÀ DELLO STATO"), ("pena", "stamp:NON È UNA PENA"), ("collettività", "crowd")]),
 (9, f"E sul museo la Cassazione è dura: secondo la sentenza, non ha agito in buona fede, perché si è fidato dei venditori e dei loro avvocati invece di verificare con le autorità italiane.",
  [("E", "i:museum|IL MUSEO"), ("buona", "stamp:BUONA FEDE? NO"), ("venditori", "ii:suit|I VENDITORI|ministry|LE AUTORITÀ"), ("italiane", "t:SECONDO LA SENTENZA")]),
 (9, f"La risposta del museo arriva a dicembre: la confisca, dice, è contraria al diritto americano e internazionale, la statua non è opera di un artista italiano e non è stata trovata in territorio italiano. Resterà a {MB}.",
  [("La", "cal:LA RISPOSTA|DIC 2018"), ("contraria", "card:IL MUSEO|confisca contraria|al diritto americano|e internazionale"), ("italiano", "map:Mare Adriatico|25|Pedaso,Croazia"), ("Resterà", "sala:statua|RESTA A MALIBU")]),
 (9, f"Nel 2019 l'Italia chiede alle autorità americane di eseguire la confisca, sulla base del trattato di assistenza giudiziaria tra i due paesi. Ma in America la sentenza italiana non vale da sola: serve un giudice americano.",
  [("Nel", "map:Washington|10|Roma,Washington|Roma>Washington"), ("trattato", "doc:TRATTATO|Italia - Stati Uniti|assistenza giudiziaria||RICOSTRUZIONE GRAFICA"), ("americano", "court:SERVE UN GIUDICE AMERICANO")]),
 # ------------------------------------------------------------------ 10 STRASBURGO
 (10, f"Ma prima ancora, il museo sceglie un altro tribunale: la Corte europea dei diritti dell'uomo, a Strasburgo. Il {TR} fa ricorso contro l'Italia.",
  [("Ma", "map:Strasburgo|20|Strasburgo"), ("Corte", "i:strasbourg|CORTE EUROPEA DEI DIRITTI DELL'UOMO"), ("ricorso", "card:IL RICORSO|J. Paul Getty Trust|contro l'Italia|n. 35271/19")]),
(10, f"Che cos'è questa Corte? È il tribunale del Consiglio d'Europa, che giudica se uno Stato ha violato la Convenzione europea dei diritti dell'uomo. Ne fanno parte quarantasei Stati. Gli Stati Uniti no: e questo, lo vedremo, conterà.",
  [("Che", "h:Che cos'è\nquesta *Corte*?"), ("Consiglio", "i:strasbourg|CONSIGLIO D'EUROPA"), ("quarantasei", "big:46|Stati membri"), ("Uniti", "stamp:USA: NO")]),
 (10, f"La tesi del museo è questa: la confisca viola il suo diritto di proprietà, protetto dalla Convenzione europea. Il museo ha comprato la statua, l'ha esposta per decenni, e ora gliela si vuole togliere.",
  [("La", "i:museum|LA TESI DEL MUSEO"), ("proprietà", "doc:CONVENZIONE EUROPEA|Protocollo 1, art. 1|protezione della proprietà||RICOSTRUZIONE GRAFICA"), ("decenni", "big:≈ 46 anni|di esposizione fino al 2024")]),
 (10, f"Il 2 maggio 2024, dopo anni di attesa, arriva la sentenza. All'unanimità, la Corte dà ragione all'Italia: la confisca non viola la Convenzione. Il diritto di proprietà del museo esiste, ma deve cedere davanti alla tutela del patrimonio culturale.",
  [("Il", "cal:2 MAGGIO|2024"), ("All'unanimità", "i:scales|ALL'UNANIMITÀ"), ("viola", "stamp:NESSUNA VIOLAZIONE"), ("proprietà", "flow:PROPRIETÀ DEL MUSEO>TUTELA DEL PATRIMONIO")]),
 (10, f"Secondo la Corte, il museo ha comprato la statua in modo negligente o non in buona fede, perché conosceva le richieste italiane. E la confisca è proporzionata allo scopo: riportare in Italia un bene del suo patrimonio culturale.",
  [("Secondo", "i:strasbourg|LA CORTE"), ("negligente", "stamp:NEGLIGENZA O MALAFEDE"), ("proporzionata", "i:scales|PROPORZIONATA"), ("patrimonio", "t:PATRIMONIO CULTURALE")]),
  (10, f"Il museo dichiara di non essere d'accordo e di poter chiedere un nuovo esame alla Grande Camera della Corte. I termini scadono dopo tre mesi, e secondo gli studi giuridici pubblicati dopo la sentenza, nessuna richiesta viene accolta: ad agosto 2024 la sentenza è definitiva.",
  [("Il", "i:museum|IL MUSEO NON È D'ACCORDO"), ("Grande", "court:GRANDE CAMERA?"), ("tre", "cal:DEFINITIVA|AGO 2024"), ("definitiva", "stamp:DEFINITIVA")]),
 (10, f"In Italia la sentenza viene accolta con soddisfazione dal ministero della Cultura, che annuncia nuovi contatti con le autorità americane. Ma c'è un limite: la Corte di Strasburgo non può obbligare gli Stati Uniti.",
  [("In", "i:ministry|IL MINISTERO DELLA CULTURA"), ("americane", "map:Washington|10|Roma,Washington"), ("limite", "stamp:UN LIMITE"), ("Stati", "t:GLI USA NON SONO VINCOLATI")]),
 (10, f"Facciamo il punto sui numeri della battaglia legale. Dal primo procedimento di Pesaro del 2007 alla sentenza di Strasburgo passano diciassette anni. Dal ritrovamento, sessanta.",
  [("Facciamo", "tl:2007|PESARO;2010|CONFISCA;2018|CASSAZIONE;2024|STRASBURGO"), ("diciassette", "big:17 anni|di battaglia legale · calcolo nostro"), ("sessanta", "big:60 anni|dal ritrovamento")]),
 (10, f"E oggi? A gennaio del 2025 un dirigente del ministero della Cultura mette in dubbio l'attribuzione a Lisippo, ma ribadisce che la statua deve tornare in Italia, a Fano.",
  [("E", "cal:IL DIBATTITO|GEN 2025"), ("dubbio", "stamp:LISIPPO?"), ("Fano", "map:Fano|60|Fano")]),
 (10, f"Secondo le ultime notizie che abbiamo trovato, ancora all'inizio del 2026, la statua è esposta in California. Fano, intanto, progetta il luogo dove accoglierla. Ma una data per il ritorno, non c'è.",
  [("Secondo", "sala:statua|ANCORA IN CALIFORNIA|LA VILLA DI MALIBU · SCHEMA|2"), ("Fano", "sala:vuoto|FANO PREPARA IL POSTO|FANO · SCHEMA"), ("data", "stamp:NESSUNA DATA")]),
 # ------------------------------------------------------------------ 11 LE DOMANDE APERTE
 (11, f"Restano molte domande. La prima: dove è stata trovata, esattamente? I giudici italiani dicono al largo di Pedaso. Il museo dice acque internazionali. Nessuna prova definitiva, a sessant'anni di distanza.",
  [("Restano", "h:Le domande\n*aperte*"), ("dove", "map:Mare Adriatico|25|Pedaso,Croazia"), ("internazionali", "ii:boat|ACQUE ITALIANE?|globe2|ACQUE INTERNAZIONALI?"), ("prova", "stamp:NESSUNA PROVA DEFINITIVA")]),
 (11, f"Ma per la Cassazione la domanda ha perso importanza: per i giudici, conta la bandiera del peschereccio. Il museo, al contrario, insiste che la statua non abbia nessun legame con il patrimonio italiano.",
  [("Ma", "court:LA CASSAZIONE"), ("bandiera", "mare:bordo|CONTA LA BANDIERA"), ("museo", "i:museum|LA TESI DEL MUSEO"), ("legame", "i:question|QUALE LEGAME?")]),
 (11, f"La seconda: è davvero di Lisippo? Non c'è una firma. L'attribuzione è nata negli anni Settanta, in Germania, mentre la statua era sul mercato. Altri studiosi l'hanno contestata, e ancora nel 2025 se ne discute.",
  [("La", "h:È davvero\ndi *Lisippo*?"), ("firma", "stamp:NESSUNA FIRMA"), ("mercato", "i:money|SUL MERCATO"), ("2025", "i:critic|SE NE DISCUTE")]),
 (11, f"La terza: che cosa ha fatto la statua tra il 1965 e i primi anni Settanta? Chi l'ha portata fuori dall'Italia, come, e quando? Le fonti non lo dicono con certezza, e su questo punto le ricostruzioni restano incomplete.",
  [("La", "h:Dov'era\ndopo il *1965*?"), ("fuori", "map:Gubbio|12|Gubbio,Monaco di Baviera|Gubbio>Monaco di Baviera"), ("certezza", "i:question|COME E QUANDO?"), ("incomplete", "stamp:NESSUNA RISPOSTA")]),
 (11, f"La quarta: i piedi e gli occhi. La statua è arrivata senza i piedi, spezzata alle caviglie, e senza il materiale degli occhi. Dove siano finiti, se in mare o altrove, nessuno lo sa.",
  [("La", "i:statue|SENZA PIEDI · SENZA OCCHI"), ("caviglie", "stamp:SPEZZATA ALLE CAVIGLIE"), ("mare", "mare:vuoto|SUL FONDO?"), ("sa", "i:question|NESSUNO LO SA")]),
 (11, f"La quinta, la più concreta: come si esegue una confisca italiana su una statua che si trova negli Stati Uniti? Serve una decisione americana. E finora, a quanto risulta, non è arrivata.",
  [("La", "h:Come si *esegue*\nla confisca?"), ("Stati", "map:Malibu|5|Fano,Malibu"), ("americana", "court:SERVE UN GIUDICE USA"), ("arrivata", "stamp:NON ANCORA")]),
 # ------------------------------------------------------------------ 12 LA LEZIONE
 (12, f"Che cosa ci insegna questa storia? Proviamo a ricavarne qualche regola utile per chiunque, perché trovare un oggetto antico non è così raro come sembra: in mare, in un campo, durante un lavoro in casa.",
  [("Che", "h:Che cosa ci\n*insegna*?"), ("trovare", "iii:boat|IN MARE|spade|IN UN CAMPO|house|IN CASA"), ("raro", "t:NON È COSÌ RARO")]),
 (12, f"Prima regola: chi trova per caso un bene archeologico deve denunciarlo. Oggi lo dice il Codice dei beni culturali, del 2004: entro ventiquattro ore, al soprintendente, al sindaco o ai carabinieri. Vale anche in mare, dove il patrimonio sommerso è protetto pure da una convenzione [dell'UNESCO|dell'unèsco] del 2001.",
  [("Prima", "big:1|denunciare"), ("Codice", "doc:CODICE DEI BENI CULTURALI|D.lgs. 42/2004|art. 90: denuncia entro 24 ore||RICOSTRUZIONE GRAFICA"), ("ventiquattro", "clock:24|ENTRO 24 ORE"), ("carabinieri", "iii:ministry|SOPRINTENDENTE|house|SINDACO|policecar|CARABINIERI")]),
 (12, f"Seconda regola: i beni archeologici ritrovati appartengono allo Stato. Ma chi li trova e li denuncia ha diritto a un premio, che secondo la legge può arrivare fino a un quarto del valore.",
  [("Seconda", "big:2|sono dello Stato"), ("Stato", "flow:REPERTO>APPARTIENE ALLO STATO"), ("premio", "big:fino a 1/4|del valore · premio di legge")]),
 (12, f"Terza regola: non tenerlo, non nasconderlo, non venderlo. Nascondere o vendere un bene archeologico è un reato, anche per chi lo compra sapendo da dove viene.",
  [("Terza", "big:3|non nascondere"), ("nasconderlo", "iii:cabbage|NON NASCONDERE|money|NON VENDERE|handcuffs|È REATO"), ("compra", "t:ANCHE PER CHI COMPRA")]),
 (12, f"Quarta regola, per chi compra arte antica, anche online: chiedere sempre la provenienza documentata. Da dove viene l'oggetto, chi l'ha posseduto, con quali permessi è uscito dal suo paese.",
  [("Quarta", "big:4|la provenienza"), ("provenienza", "doc:PROVENIENZA|chi l'ha posseduto|da dove viene|con quali permessi|RICOSTRUZIONE GRAFICA"), ("permessi", "i:passport|I PERMESSI")]),
 (12, f"Quinta regola: se qualcosa non torna, verificare con le autorità e non solo con il venditore. È esattamente il punto su cui, secondo la Cassazione e la Corte europea, il museo ha sbagliato.",
  [("Quinta", "big:5|verificare"), ("autorità", "ii:suit|SOLO IL VENDITORE?|ministry|LE AUTORITÀ"), ("sbagliato", "stamp:IL PUNTO DECISIVO")]),
 (12, f"Queste sono indicazioni generali, non una consulenza legale. Per un caso concreto, la cosa giusta è rivolgersi alla soprintendenza o ai carabinieri del nucleo per la tutela del patrimonio culturale.",
  [("Queste", "i:warn|INDICAZIONI GENERALI"), ("consulenza", "t:NON È CONSULENZA LEGALE"), ("soprintendenza", "ii:ministry|SOPRINTENDENZA|policecar|CARABINIERI TPC")]),
 # ------------------------------------------------------------------ VERDETTO
 (13, f"Ricapitoliamo il fascicolo. Uno: nell'estate del 1964 dei pescatori di Fano tirano su con la rete una statua greca di bronzo, e non la denunciano.",
  [("Ricapitoliamo", "cover"), ("Uno", "mare:rete|1 · LA RETE")]),
 (13, f"Due: la statua viene nascosta, venduta per {M35} di lire e portata fuori dall'Italia. I processi degli anni Sessanta finiscono con l'assoluzione di tutti gli imputati.",
  [("Due", "i:cabbage|2 · NASCOSTA"), ("venduta", "big:3,5 mln|di lire · 1964"), ("portata", "map:Gubbio|12|Gubbio,Monaco di Baviera|Gubbio>Monaco di Baviera"), ("processi", "court:I PROCESSI · FINO AL 1970"), ("l'assoluzione", "stamp:TUTTI ASSOLTI")]),
 (13, f"Tre: nel 1977 il museo {GT} la compra per {M395} di dollari, e dal 1978 la espone a {MB}.",
  [("Tre", "big:3,95 mln $|1977"), ("compra", "map:Malibu|4|Fano,Malibu|Fano>Malibu"), ("espone", "sala:statua|MALIBU · DAL 1978")]),
 (13, f"Quattro: nel 2010 il giudice di Pesaro ordina la confisca, e nel 2018 la Cassazione la rende definitiva. Cinque: nel 2024 la Corte europea dei diritti dell'uomo dà ragione all'Italia, all'unanimità.",
  [("Quattro", "court:CONFISCA · 2010-2018"), ("Cinque", "i:strasbourg|STRASBURGO · 2024")]),
 (13, f"Sei: la statua, a quanto risulta, è ancora in California. Fano aspetta, e manca ancora una decisione americana.",
  [("Sei", "sala:statua|ANCORA IN CALIFORNIA"), ("Fano", "map:Malibu|4|Malibu,Fano|Malibu>Fano")]),
 (13, f"E voi che cosa pensate? La statua deve tornare a Fano, o conta di più chi l'ha comprata e la espone da quasi cinquant'anni? Scrivetelo nei commenti.",
  [("E", "h:E *voi*\ncosa ne pensate?"), ("Fano", "ii:statue|A FANO?|museum|A MALIBU?"), ("commenti", "i:envelope|SCRIVETELO NEI COMMENTI")]),
 (13, f"Iscriviti a Fascicolo Italia: ogni giorno un nuovo caso.",
  [("Iscriviti", "subscribe")]),
]
